CREATE POLICY "Assigned students read kit source pages" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'tutoring-materials' AND (storage.foldername(name))[1] = 'kits' AND EXISTS (SELECT 1 FROM public.student_assignments a WHERE a.student_id = auth.uid() AND a.payload->>'kit_id' = (storage.foldername(name))[2] AND name = ANY (SELECT jsonb_array_elements_text(COALESCE(a.payload->'page_paths', '[]'::jsonb)))));